-- Aus AbState.shn generiert (777 Zeilen, 19 Spalten).
-- Spaltennamen/-typen 1:1 aus der echten Client-.shn-Datei uebernommen (ggf. umbenannt, siehe unten),
-- damit sie exakt zu den row["..."]-Zugriffen im vorhandenen C#-Code passen.
DROP TABLE IF EXISTS `data_abstate`;
CREATE TABLE `data_abstate` (
  `ID` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `InxName` VARCHAR(32) NOT NULL DEFAULT '',
  `AbStataIndex` INT UNSIGNED NOT NULL DEFAULT 0,
  `KeepTimeRatio` INT UNSIGNED NOT NULL DEFAULT 0,
  `KeepTimePower` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `StateGrade` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `PartyState1` VARCHAR(32) NOT NULL DEFAULT '',
  `PartyState2` VARCHAR(32) NOT NULL DEFAULT '',
  `PartyState3` VARCHAR(32) NOT NULL DEFAULT '',
  `PartyState4` VARCHAR(32) NOT NULL DEFAULT '',
  `PartyState5` VARCHAR(32) NOT NULL DEFAULT '',
  `PartyRange` INT UNSIGNED NOT NULL DEFAULT 0,
  `PartyEnchantNumber` INT UNSIGNED NOT NULL DEFAULT 0,
  `SubAbState` VARCHAR(32) NOT NULL DEFAULT '',
  `DispelIndex` INT UNSIGNED NOT NULL DEFAULT 0,
  `SubDispelIndex` INT UNSIGNED NOT NULL DEFAULT 0,
  `AbStateSaveType` INT UNSIGNED NOT NULL DEFAULT 0,
  `MainStateInx` VARCHAR(32) NOT NULL DEFAULT '',
  `Duplicate` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

